let gulp=require("gulp"),strip=require("gulp-strip-comments"),cleanCSS=require("gulp-clean-css"),uglify=require("gulp-uglify");gulp.task("clean-php",()=>gulp.src("**/*.php").pipe(strip()).pipe(gulp.dest("dist"))),gulp.task("clean-css",()=>gulp.src("**/*.css").pipe(strip()).pipe(cleanCSS()).pipe(gulp.dest("dist"))),gulp.task("clean-js",()=>gulp.src("**/*.js").pipe(strip()).pipe(uglify()).pipe(gulp.dest("dist"))),gulp.task("default",gulp.parallel("clean-php","clean-css","clean-js"));